async ({ delivery: { validate }, shell: { execFile } }) => {
  const [v, audit, pack] = await Promise.all([
    validate({ coverage: true, packageCheck: true }),
    execFile("npm", ["audit", "--omit=dev"]),
    execFile("npm", ["pack", "--dry-run"], { maxLines: 15, truncate: "tail" }),
  ]);
  const q = await execFile("npm", ["run", "quality:audit"], { maxLines: 20, truncate: "tail" });
  const diff = await execFile("git", ["diff", "--stat"]);
  return { v, audit: audit.stdout.slice(-300), auditCode: audit.code, pack: pack.stderr.slice(-800), q: { code: q.code, out: q.stdout.slice(-600) }, diff: diff.stdout };
}
